"""Half-open integer interval operations."""


def _clean(intervals):
    return [(s, e) for s, e in intervals if s < e]


def merge(intervals):
    cleaned = _clean(intervals)
    if not cleaned:
        return []
    cleaned.sort()
    merged = [cleaned[0]]
    for start, end in cleaned[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            if end > last_end:
                merged[-1] = (last_start, end)
        else:
            merged.append((start, end))
    return merged


def free_gaps(intervals, window):
    ws, we = window
    if ws >= we:
        return []
    clipped = [(s, e) for s, e in _clean(intervals) if s < we and e > ws]
    if not clipped:
        return [(ws, we)]
    clipped.sort()
    merged = [clipped[0]]
    for start, end in clipped[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            if end > last_end:
                merged[-1] = (last_start, end)
        else:
            merged.append((start, end))
    gaps = []
    cursor = ws
    for start, end in merged:
        if start > cursor:
            gaps.append((cursor, start))
        if end > cursor:
            cursor = end
    if cursor < we:
        gaps.append((cursor, we))
    return gaps


def max_overlap(intervals):
    import heapq

    starts = sorted((s for s, e in _clean(intervals)))
    if not starts:
        return 0
    ends = [e for s, e in _clean(intervals)]
    ends.sort()
    # Sweep: two pointers over sorted starts and ends.
    # A point covered by interval [s, e) counts at any x with s <= x < e.
    # Classic approach: sort events; at equal coordinate, ends (half-open)
    # do not overlap with starts at the same point, so process ends first.
    events = []
    for s, e in _clean(intervals):
        events.append((s, 1))
        events.append((e, -1))
    events.sort(key=lambda ev: (ev[0], ev[1]))
    best = 0
    current = 0
    for _, delta in events:
        current += delta
        if current > best:
            best = current
    del starts, ends
    return best

"""LRU cache with per-entry time-to-live."""

import time
from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self._capacity = capacity
        self._clock = clock
        # key -> (value, deadline); deadline is None for entries that never
        # expire. OrderedDict preserves recency: least recent at the front.
        self._entries = OrderedDict()

    def _purge_expired(self):
        now = self._clock()
        expired = [
            key
            for key, (_value, deadline) in self._entries.items()
            if deadline is not None and now >= deadline
        ]
        for key in expired:
            del self._entries[key]
        return len(expired)

    def put(self, key, value, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be positive")
        if key not in self._entries:
            self._purge_expired()
            if len(self._entries) >= self._capacity:
                self._entries.popitem(last=False)
        deadline = None if ttl is None else self._clock() + ttl
        self._entries[key] = (value, deadline)
        self._entries.move_to_end(key)

    def get(self, key, default=None):
        entry = self._entries.get(key)
        if entry is None:
            return default
        value, deadline = entry
        if deadline is not None and self._clock() >= deadline:
            del self._entries[key]
            return default
        self._entries.move_to_end(key)
        return value

    def __contains__(self, key):
        entry = self._entries.get(key)
        if entry is None:
            return False
        _value, deadline = entry
        return deadline is None or self._clock() < deadline

    def __len__(self):
        self._purge_expired()
        return len(self._entries)

    def keys(self):
        self._purge_expired()
        return list(self._entries)

    def evict_expired(self):
        return self._purge_expired()

"""Arithmetic expression evaluator: tokenizer + recursive-descent parser."""

import re

_TOKEN_RE = re.compile(
    r"\s*(?:(?P<number>\d+\.\d+|\d+|\.\d+)"
    r"|(?P<name>[A-Za-z_][A-Za-z_0-9]*)"
    r"|(?P<op>\*\*|//|[+\-*/%(),]))"
)

# name -> (min_args, max_args); max_args None means unbounded
_FUNCTIONS = {
    "min": (1, None),
    "max": (1, None),
    "abs": (1, 1),
}


def _tokenize(text):
    tokens = []
    pos = 0
    length = len(text)
    while pos < length:
        match = _TOKEN_RE.match(text, pos)
        if match is None:
            if text[pos:].strip() == "":
                break
            raise ValueError(
                "unexpected character at position %d: %r" % (pos, text[pos])
            )
        pos = match.end()
        kind = match.lastgroup
        tokens.append((kind, match.group(kind)))
    return tokens


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def advance(self):
        token = self.peek()
        if token is None:
            raise ValueError("unexpected end of expression")
        self.pos += 1
        return token

    def expect(self, kind, value):
        token = self.advance()
        if token[0] != kind or token[1] != value:
            raise ValueError("expected %r but got %r" % (value, token[1]))
        return token

    def parse(self):
        if not self.tokens:
            raise ValueError("empty expression")
        value = self.expression()
        if self.pos != len(self.tokens):
            raise ValueError("unexpected token %r" % (self.peek()[1],))
        return value

    def expression(self):
        value = self.term()
        while True:
            token = self.peek()
            if token is not None and token[0] == "op" and token[1] in ("+", "-"):
                self.pos += 1
                rhs = self.term()
                value = value + rhs if token[1] == "+" else value - rhs
            else:
                return value

    def term(self):
        value = self.unary()
        while True:
            token = self.peek()
            if token is not None and token[0] == "op" and token[1] in ("*", "/", "//", "%"):
                self.pos += 1
                rhs = self.unary()
                op = token[1]
                if op == "*":
                    value = value * rhs
                elif op == "/":
                    value = value / rhs
                elif op == "//":
                    value = value // rhs
                else:
                    value = value % rhs
            else:
                return value

    def unary(self):
        token = self.peek()
        if token is not None and token[0] == "op" and token[1] in ("+", "-"):
            self.pos += 1
            value = self.unary()
            return -value if token[1] == "-" else value
        return self.power()

    def power(self):
        base = self.primary()
        token = self.peek()
        if token is not None and token[0] == "op" and token[1] == "**":
            self.pos += 1
            exponent = self.unary()  # right-associative; exponent may be unary
            return base ** exponent
        return base

    def primary(self):
        token = self.peek()
        if token is None:
            raise ValueError("unexpected end of expression")
        kind, value = token
        if kind == "number":
            self.pos += 1
            return float(value) if "." in value else int(value)
        if kind == "name":
            self.pos += 1
            if value not in _FUNCTIONS:
                raise ValueError("unknown name: %r" % value)
            return self.call(value)
        if kind == "op" and value == "(":
            self.pos += 1
            inner = self.expression()
            self.expect("op", ")")
            return inner
        raise ValueError("unexpected token %r" % value)

    def call(self, name):
        self.expect("op", "(")
        args = []
        token = self.peek()
        if token is None or token != ("op", ")"):
            args.append(self.expression())
            while True:
                token = self.peek()
                if token is not None and token[0] == "op" and token[1] == ",":
                    self.pos += 1
                    args.append(self.expression())
                else:
                    break
        self.expect("op", ")")
        min_args, max_args = _FUNCTIONS[name]
        if len(args) < min_args or (max_args is not None and len(args) > max_args):
            raise ValueError(
                "%s expects %s argument(s), got %d"
                % (name, min_args if max_args == min_args else "1+", len(args))
            )
        if name == "abs":
            return abs(args[0])
        if name == "min":
            return min(args)
        return max(args)


def evaluate(text):
    if not isinstance(text, str):
        raise ValueError("expression must be a string")
    return _Parser(_tokenize(text)).parse()
